"""Integrate lead-owned alternate-pixel and new-S105 exception checks."""
import hashlib,json,re
from pathlib import Path
B=Path(__file__).resolve().parent;p=B/'write_reports.py';before=hashlib.sha256(p.read_bytes()).hexdigest();s=p.read_text(encoding='utf-8')
updates={
'T011': "'T011':dict(verdict='REFUTED',completion='COMPLETE',limitations='The S96 QLP dip resumes after a 1.3 d gap, but target-centered S96 TESSCut raw pixels show an opposite-sign brightening/recovery. S105 does not cover the next +6 Gaia-cycle center at 4234.5 BTJD; its strong bright spike at 4219 is not an eclipse.',next='No eclipse follow-up from the S96 flag; independently investigate the QLP/raw-pixel discrepancy if this star is otherwise of interest.',evidence='The screened S96 raw QLP SAP appears about 6% low immediately after a 1.3 d gap and rises over 0.7 d, but a target-centered 5x5 extraction from the same S96 TESSCut raw pixels is 54.7 ppt brighter than pre/post baselines during 3921.796-3921.946 BTJD (65 core, 432/432 baseline quality-zero samples). Its pixel light curve is a positive recovery, contradicting an astrophysical eclipse deficit in the target pixels. Conditional Gaia-period windows S102 +4 and S104 +5 are fully covered at +/-0.6 d with 519/514 samples and essentially zero deficit. New S105 raw pixels cover 4206.21-4233.00 BTJD, showing no comparable dip; the next conditional Gaia center lies outside coverage. The candidate eclipse flag is a gap/processing artifact; this does not deny the Gaia binary.'),",
'T016': "'T016':dict(verdict='REFUTED',completion='COMPLETE',limitations='S19 is close to a sector edge; the QLP feature is contradicted by independent raw-pixel extraction and need not be treated as an eclipse center. Conditional Gaia-period nulls are supportive, not the sole refutation.',next='No eclipse follow-up from the S19 flag; test any future independent dip if found.',evidence='The sole S19 QLP screened feature at 1840.639 BTJD is a depressed segment followed by an abrupt rise. Target-centered 5x5 S19 TESSCut raw pixels are flat through the screened core and then brighten sharply; core is 2.0 ppt brighter than pre/post baselines (7 core, 12/9 baseline quality-zero samples), opposite the proposed eclipse. Conditional Gaia-period S40 +11 and S73 +28 windows are flat at the narrow tested cores. Current MAST sector listing adds no later occasion. The positive raw-pixel mismatch and step morphology refute the selected eclipse flag.'),",
'T018': "'T018':dict(verdict='REFUTED',completion='COMPLETE',limitations='S94 remains broad variable structure; the short S104 QLP trough is not reproduced as a target-centered raw-pixel deficit. No claim excludes a hidden unrelated eclipse.',next='Do not use S94/S104 screened times as a binary ephemeris; re-evaluate only a fresh repeatable dip.',evidence='The two QLP windows S94 3874.77 and S104 4179.43 BTJD differ in width and are separated by 304.66 d, or 5.42 Gaia periods. S94 is a multi-day sloped trough. At S104 the target-centered 5x5 TESSCut raw pixels have a smooth decline through the selected window and a -0.11 ppt core deficit relative to pre/post baselines (78 core, 108/108 baseline quality-zero samples), not a localized 5.5 ppt eclipse. The tentative Gaia-clock S67 core is flat; current MAST sectors match the five cached sectors. Positive contrary pixel morphology refutes the selected paired-eclipse interpretation.'),",
'T019': "'T019':dict(verdict='REFUTED',completion='COMPLETE',limitations='New S105 starts 0.16 d before the conditional Gaia repeat, so it does not test a full ingress; the S103 alternate-pixel morphology is the decisive contrary evidence.',next='Do not use the flagged troughs as eclipse times; obtain an independent repeat only if later photometry reveals a clean dip.',evidence='S13/S94/S101 QLP flags lie on broad slopes or gap-associated changes. S103 QLP shows a ~14 ppt trough near 4165.0 BTJD, but the target-centered 5x5 TESSCut raw pixels decline gradually into the screen time, rise into a local bright cusp, then jump downward after a gap and resume a decline; the selected core is 3.37 ppt brighter than the separated baselines (108 core, 302/259 baseline quality-zero samples). The difference pattern is a position/level change, not a centered flux deficit. New S105 pixels cover 4205.818-4233.006 BTJD; around the conditional +1 Gaia center 4205.974 the flux smoothly declines from above the later baseline, with no 14 ppt repeat, though the sector edge leaves ingress untested. These are positive contrary shapes for the selected eclipse flags.'),",
}
for sid,line in updates.items():
    s,n=re.subn(r"^'"+sid+r"':dict\(.*$",line,s,flags=re.M)
    assert n==1,(sid,n)
p.write_text(s,encoding='utf-8');after=hashlib.sha256(p.read_bytes()).hexdigest()
(B/'lead-exception-revision.json').write_text(json.dumps({'before_sha256':before,'after_sha256':after,'author':'Sol lead','reason':'Four ambiguous QLP features contradicted by target-centered independent raw-pixel extraction; newly available S105 assessed for T011/T019.'},indent=2)+'\n',encoding='utf-8')
print(before,after)
